def get_item(items, used_names):
    # heuristic to avoid NYC names if possible
    avoid_terms = ["NYC", "York", "Manhattan", "Brooklyn", "Williamsburg", "Soho", "Harlem"]

    # First pass: try to find one that doesn't contain avoid terms
    for item in items:
        name = item.get('NAME') or item.get('Name')
        if name in used_names:
            continue

        if not any(term in name for term in avoid_terms):
            used_names.add(name)
            return item

    # Second pass: take any available
    for item in items:
        name = item.get('NAME') or item.get('Name')
        if name not in used_names:
            used_names.add(name)
            return item

    return items[0] if items else None # Fallback

